contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint a) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= a);
        // Optionally seed the contract with unrelated ether via a deposit from
        // another context is not possible; instead deposit and record that the
        // rule targets the no-credit case, so use a = 0 semantics: only proceed
        // when we guarantee the caller has no credit on a fresh contract.
        bool reverted;
        uint balBefore = address(c).balance;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(!reverted && address(c).balance == balBefore);
    }
    receive() external payable {}
}

