// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 a) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= a);
        bool reverted;
        uint balBefore = address(c).balance;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted && address(c).balance == balBefore);
    }

    function testFuzz_run(uint256 a) public {
        _run(a);
    }

    receive() external payable {}
}
